import {swrLegend} from './swr-legend.js';
import {returnLabel} from './return-path.js';
import {returnConfiguration} from './accurate-geometry.js';
import {BANDS,resizeAntenna} from './length-tools.js';
import {BAND_EDGES,sweepPlan,scoreSweep,sweepGeometry,sweepX,sweepY,sweepIdentity} from './band-sweep.js';
import {formatLength,validateLength} from './units.js';
import {RATIOS,formatSWR,ohms} from './matching.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mhz=f=>f.toFixed(4).replace(/0$/,'');
export function initWireSweep({parent,getConfig,getUnits,download,setRatio}){
 const key='fieldlab.wire-sweep.v1';let units=getUnits(),length=getConfig().setup.length,edges=structuredClone(BAND_EDGES),points=41,worker=null,results=[],meta=null,dirty=false,running=false,status='Enter an installed wire length, then run a sweep.',signature='';
 try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved){if(saved.length>=.1&&saved.length<=170)length=saved.length;if([21,41,81].includes(saved.points))points=saved.points;for(const b of BANDS)if(Array.isArray(saved.edges?.[b.id])&&saved.edges[b.id].length===2)edges[b.id]=saved.edges[b.id];}}catch{}
 const card=document.createElement('section');card.className='rw-card rw-sweep-card';card.id='rw-sweep-section';parent.append(card);
 card.innerHTML=`<div class="rw-section-head"><h2>SWR for one wire length</h2><button class="text-button" id="rw-sweep-export" hidden>↓ Sweep CSV</button></div><div class="rw-sweep-controls"><label>Installed total length <span><input id="rw-sweep-length" type="text"><span id="rw-sweep-unit"></span></span></label><button id="rw-sweep-copy" class="text-button">Use installation length</button><label>Unun ratio <select id="rw-sweep-ratio">${RATIOS.map(r=>`<option value="${r}">${r}:1${r===1?' / direct':''}</option>`).join('')}</select></label><label>Resolution <select id="rw-sweep-points"><option value="21">21 points / band</option><option value="41">41 points / band</option><option value="81">81 points / band</option></select></label><button id="rw-sweep-run" class="button dark">Calculate SWR plots</button><button id="rw-sweep-cancel" class="text-button" hidden>Cancel sweep</button></div><p id="rw-sweep-matching" class="solve-small"></p><p id="rw-sweep-return" class="rw-return-summary"></p><details class="rw-sweep-edges"><summary>Band edges · edit for your region or operating window</summary><p class="solve-small">Defaults: US reference band limits from <a href="https://www.arrl.org/frequency-allocations" target="_blank" rel="noopener">ARRL</a>, editable in MHz. These windows do not indicate license or mode privileges. The 60 m default is only the 5.3515–5.3665 MHz segment; separate channels are not included.</p><div id="rw-sweep-edges"></div></details><p id="rw-sweep-error" class="solve-error" role="alert" hidden></p><p id="rw-sweep-status" class="tune-status" role="status"></p><p class="solve-small">Uses the selected design bands above and the installation at left. Gold: selected unun ratio · gray dashed: direct feed · green shading: entered band window · cyan dashed lines: band edges · horizontal dashed line: SWR 2:1. Curves include 20% of the band width outside each edge where possible. SWR above 20 is clipped on the plot; readouts retain the value. Matching is an ideal ratio; no tuner or feedline is simulated.</p><div id="rw-sweep-plots" class="rw-sweep-plots"></div>`;
 const $=id=>card.querySelector('#'+id),fmt=()=>formatLength(length,units)+(units==='m'?' m':''),selected=()=>BANDS.filter(b=>getConfig().selected.includes(b.id));
 const save=()=>{try{localStorage.setItem(key,JSON.stringify({length,edges,points}));}catch{}};
 function error(text=''){$('rw-sweep-error').hidden=!text;$('rw-sweep-error').textContent=text;}
 function identity(){return sweepIdentity(getConfig());}
 function controls(){const cfg=getConfig(),ret=returnConfiguration(cfg.setup);$('rw-sweep-return').textContent=`Modeled return: ${returnLabel(ret)} · ${ret.count} × ${formatLength(ret.length,units)}${units==='m'?' m':''} · ${ret.mode==='ground'?'model height '+formatLength(ret.groundHeight,units)+(units==='m'?' m':'')+' above soil; shared drop included':ret.slope+'° down'}${ret.diameter?' · '+ret.diameter+' mm':''}. ${ret.mode==='ground'?'Raised-wire approximation only; no soil contact, burial or insulation. Compare model clearances; this is not a validated on-ground SWR prediction.':ret.mode==='coax'?'Bare exterior conductor up to the choke; jacket, coax loss and real choke response are excluded.':'No additional coax exterior is included.'} No earth connection. SWR is at the ideal unun input before a tuner.`;$('rw-sweep-ratio').value=cfg.ratio;$('rw-sweep-matching').textContent=`Gold curve: ${cfg.ratio}:1 ${cfg.ratio===1?'direct feed':'ideal unun'} into ${cfg.setup.referenceZ} Ω. Shared with the sidebar matching target; changing either selector updates existing curves instantly.`; $('rw-sweep-run').disabled=running;$('rw-sweep-run').textContent=running?'Calculating…':'Calculate SWR plots';$('rw-sweep-cancel').hidden=!running;$('rw-sweep-export').hidden=!results.length;$('rw-sweep-status').textContent=status;}
 function cancel(message='Sweep canceled. Run again to calculate this installation.') {if(worker){worker.terminate();worker=null;running=false;status=message;controls();}}
 function clear(message){cancel(message);results=[];meta=null;status=message;render();}
 function commitLength(){if(!dirty)return true;const r=validateLength($('rw-sweep-length').value,units,.1,170);$('rw-sweep-length').setAttribute('aria-invalid',!!r.error);if(r.error){error(r.error);return false;}length=r.meters;dirty=false;error();save();clear('Length changed. Calculate SWR plots to update.');return true;}
 function fields(){if(!dirty&&document.activeElement!==$('rw-sweep-length'))$('rw-sweep-length').value=formatLength(length,units);$('rw-sweep-unit').textContent=units;$('rw-sweep-points').value=points;
  $('rw-sweep-edges').innerHTML=selected().map(b=>`<label>${b.name}<span><input type="number" min="1.8" max="60" step="any" data-edge="${b.id}" data-side="0" aria-label="${b.name} lower band edge MHz" value="${esc(edges[b.id][0])}"> – <input type="number" min="1.8" max="60" step="any" data-edge="${b.id}" data-side="1" aria-label="${b.name} upper band edge MHz" value="${esc(edges[b.id][1])}"> MHz</span></label>`).join('');
  for(const input of card.querySelectorAll('[data-edge]'))input.oninput=input.onchange=()=>{const number=Number(input.value);if(!input.value||!input.checkValidity()){input.reportValidity();return;}edges[input.dataset.edge][Number(input.dataset.side)]=number;save();clear('Band edges changed. Calculate SWR plots to update.');};
 }
 function render(){controls();const cfg=getConfig();$('rw-sweep-plots').innerHTML=results.map(b=>{const r=scoreSweep(b,{ratio:cfg.ratio,reference:cfg.setup.referenceZ}),g=sweepGeometry(r),x=f=>sweepX(f,r),y=sweepY;return `<article class="rw-band-plot" data-band="${b.id}"><h3>${b.name} <span>${mhz(b.low)}–${mhz(b.high)} MHz</span></h3>${swrLegend(cfg.ratio,cfg.setup.referenceZ,'unun')}<p class="rw-sweep-readout" data-readout>Hover or use arrow keys to inspect</p><svg viewBox="0 0 600 170" tabindex="0" role="img" aria-label="${b.name} estimated SWR for ${esc(fmt())}; band edges ${mhz(b.low)} and ${mhz(b.high)} MHz"><rect x="48" y="34" width="516" height="100" class="rw-sweep-outside"/><rect x="${g.lowX}" y="34" width="${g.highX-g.lowX}" height="100" class="rw-sweep-band"/>${[1,2,5,10,20].map(v=>`<path d="M48 ${y(v)}H564" class="swr-grid${v===2?' swr-two':''}"/><text x="40" y="${y(v)+3}" text-anchor="end">${v}${v===20?'+':''}</text>`).join('')}<path d="${g.direct}" class="swr-direct"/><path d="${g.selected}" class="swr-selected"/>${[b.low,b.high].map((f,i)=>`<path d="M${x(f)} 29V137" class="rw-band-edge"/><text class="rw-band-edge-label" x="${x(f)}" y="17" text-anchor="${i?'end':'start'}">${i?'Upper':'Lower'} ${mhz(f)}</text>`).join('')}<text x="48" y="157" text-anchor="start">${mhz(b.min)}</text><text x="306" y="157" text-anchor="middle">Frequency · MHz</text><text x="564" y="157" text-anchor="end">${mhz(b.max)}</text><path data-cursor d="" class="rw-sweep-cursor" hidden/></svg><p class="solve-small">${esc(fmt())} · ${cfg.ratio}:1 · ${cfg.setup.referenceZ} Ω · Best sampled in band: ${formatSWR(r.best.swr)} at ${mhz(r.best.freq)} MHz · Worst sampled: ${formatSWR(r.worst)}</p></article>`;}).join('');
  for(const el of card.querySelectorAll('.rw-band-plot')){const svg=el.querySelector('svg'),r=scoreSweep(results.find(b=>b.id===el.dataset.band),{ratio:cfg.ratio,reference:cfg.setup.referenceZ});let index=0;const inspect=i=>{index=Math.max(0,Math.min(r.samples.length-1,i));const p=r.samples[index],cursor=el.querySelector('[data-cursor]');cursor.setAttribute('d',`M${sweepX(p.freq,r)} 29V137`);cursor.removeAttribute('hidden');el.querySelector('[data-readout]').textContent=`${mhz(p.freq)} MHz · ${p.freq>=r.low&&p.freq<=r.high?'In band window':'Outside band window'} · ${cfg.ratio}:1 ${formatSWR(p.swr)} · direct ${formatSWR(p.directSWR)} · Z ${ohms(p.selected.presented[0])} (raw ${ohms(p.selected.raw[0])})`;};svg.onpointermove=e=>{const rect=svg.getBoundingClientRect(),f=r.min+(((e.clientX-rect.left)/rect.width*600-48)/516)*(r.max-r.min);inspect(r.samples.reduce((best,p,i)=>Math.abs(p.freq-f)<Math.abs(r.samples[best].freq-f)?i:best,0));};const hide=()=>el.querySelector('[data-cursor]').setAttribute('hidden','');svg.onpointerleave=hide;svg.onblur=hide;svg.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();inspect(e.key==='Home'?0:e.key==='End'?r.samples.length-1:index+(e.key==='ArrowRight'?1:-1));}};}
 }
 $('rw-sweep-length').oninput=()=>{dirty=true;cancel('Length is being edited. Calculate again after entering it.');};$('rw-sweep-length').onchange=commitLength;$('rw-sweep-length').onblur=commitLength;$('rw-sweep-length').onkeydown=e=>{if(e.key==='Enter'){if(commitLength())run();}if(e.key==='Escape'){dirty=false;$('rw-sweep-length').value=formatLength(length,units);error();}};
 $('rw-sweep-copy').onclick=()=>{length=getConfig().setup.length;dirty=false;fields();save();clear('Installation length copied. Calculate SWR plots to update.');};
 $('rw-sweep-points').onchange=()=>{points=Number($('rw-sweep-points').value);save();clear('Resolution changed. Calculate SWR plots to update.');};
 function run(){if(!commitLength())return;try{error();for(const input of card.querySelectorAll('[data-edge]')){if(!input.value||!input.checkValidity())throw Error('Enter valid band edges within 1.8–60 MHz.');edges[input.dataset.edge][Number(input.dataset.side)]=Number(input.value);}save();const cfg=getConfig(),plan=sweepPlan(selected(),edges,points);resizeAntenna(cfg.setup,length,cfg.lPolicy);cancel();results=[];meta=null;signature=identity();status=`Calculating ${fmt()} across ${plan.length} bands…`;running=true;render();worker=new Worker(new URL('./length-worker.js',import.meta.url),{type:'module'});const taskWorker=worker;worker.onmessage=({data})=>{if(worker!==taskWorker)return;if(data.progress){status=`${fmt()} · ${data.progress}`;controls();}if(data.band){results.push(data.band);render();}if(data.sweepComplete){meta=data.sweepComplete;worker.terminate();worker=null;running=false;status=`Complete · ${fmt()} · ${results.length} bands · ${meta.segmentCount} segments · ${points} grid points plus exact band edges. Return: ${meta.returnDescription}. ${meta.warnings.join(' ')} No finer-mesh convergence check; inspect in the workbench before relying on a design. Samples can miss narrow SWR peaks.`;render();}if(data.error){cancel();error(data.error);status='Sweep failed. Check the installation and length.';controls();}};worker.onerror=e=>{cancel();error('SWR worker failed: '+e.message);};worker.postMessage({task:'sweep',state:cfg.setup,length,lPolicy:cfg.lPolicy,bands:plan});}catch(e){error(e.message);}}
 $('rw-sweep-ratio').onchange=()=>{const ratio=Number($('rw-sweep-ratio').value);if(RATIOS.includes(ratio))setRatio(ratio);};
 $('rw-sweep-run').onclick=run;$('rw-sweep-cancel').onclick=()=>cancel();
 $('rw-sweep-export').onclick=()=>{const cfg=getConfig(),lines=['# FieldLab sampled NEC SWR sweep; ideal transformer, no tuner or feedline','# '+JSON.stringify({length,ratio:cfg.ratio,reference:cfg.setup.referenceZ,state:meta?.state}),'band,frequency_MHz,lower_edge_MHz,upper_edge_MHz,in_band,raw_R,raw_X,presented_R,presented_X,direct_SWR,selected_SWR'];for(const b of results)for(const p of scoreSweep(b,{ratio:cfg.ratio,reference:cfg.setup.referenceZ}).samples)lines.push([b.name,p.freq,b.low,b.high,p.freq>=b.low&&p.freq<=b.high,...p.selected.raw[0],...p.selected.presented[0],p.directSWR,p.swr].join(','));download('fieldlab-wire-swr-bands.csv',lines.join('\n'),'text/csv');};
 signature=identity();fields();render();return {commitLength,cancel,invalidate(){const next=identity();if(next!==signature){signature=next;fields();clear('Installation or selected bands changed. Calculate SWR plots to update.');}},refresh(){render();},syncUnits(next){units=next;fields();render();}};
}
